#!/usr/bin/env python3
import csv, io, json, sys, os
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        return f.read()


def csv_rows(path, delimiter=","):
    text = read_text(path)
    rdr = csv.DictReader(io.StringIO(text), delimiter=delimiter)
    for row in rdr:
        row = {(k or "").strip(): (v or "").strip() for k, v in row.items() if k is not None}
        if any(row.values()):
            yield row


def files(d):
    out = []
    for root, _, fs in os.walk(d):
        for f in fs:
            out.append(os.path.join(root, f))
    return sorted(out)


def to_epoch(dt):
    return int(dt.timestamp()) if dt.tzinfo else None


def local_to_utc(naive, tz, fold=0):
    return int(naive.replace(tzinfo=tz, fold=fold).timestamp())


def p_abbr(path, tz):
    for r in csv_rows(path):
        d = datetime.strptime(r["Date"], "%m/%d/%Y")
        t = datetime.strptime(r["Time"].upper(), "%I:%M:%S %p")
        n = d.replace(hour=t.hour, minute=t.minute, second=t.second)
        fold = 1 if r.get("Zone", "").upper().endswith("ST") else 0
        yield r["Record"], r["Badge"], r["Punch"].upper(), local_to_utc(n, tz, fold)


def p_epoch(path, tz):
    for line in read_text(path).splitlines():
        line = line.strip()
        if not line:
            continue
        o = json.loads(line)
        if o.get("heartbeat") or "id" not in o:
            continue
        if "ts_ms" in o:
            ts = int(o["ts_ms"]) // 1000
        elif "ts" in o:
            ts = int(o["ts"])
        else:
            continue
        yield str(o["id"]), o["emp"], o["dir"].upper(), ts


def p_offset(path, tz):
    for r in csv_rows(path, ";"):
        ev = r["event"].lower()
        d = "IN" if ev == "clock_in" else "OUT"
        yield r["punch_id"], r["employee"], d, to_epoch(datetime.fromisoformat(r["timestamp"]))


def p_legacy(path, tz):
    for line in read_text(path).splitlines():
        if not line.startswith("D"):
            continue
        pid = line[1:9]
        badge = "E" + line[9:15].strip()
        d = "IN" if line[15] == "I" else "OUT"
        n = datetime.strptime(line[16:30], "%Y%m%d%H%M%S")
        probe = n.replace(tzinfo=tz)
        std = probe.utcoffset() - (probe.dst() or timedelta(0))
        ts = int((n.replace(tzinfo=UTC) - std).timestamp())
        yield pid, badge, d, ts


def p_de(path, tz):
    for r in csv_rows(path, "\t"):
        d = datetime.strptime(r["Datum"], "%d.%m.%Y")
        h, m = r["Uhrzeit"].split(":")[:2]
        n = d.replace(hour=int(h), minute=int(m))
        fold = 1 if r.get("Zeitzone", "").upper() == "MEZ" else 0
        yield r["Nr"], r["Ausweis"], "IN" if r["Buchung"].upper() == "K" else "OUT", local_to_utc(n, tz, fold)


def p_localcsv(path, tz):
    for r in csv_rows(path):
        n = datetime.strptime(r["local_time"], "%Y-%m-%d %H:%M:%S")
        yield r["punch_ref"], r["employee_id"], r["direction"].upper(), local_to_utc(n, tz, 0)


def p_localjsonl(path, tz):
