    pend = date.fromisoformat(period["end"])
    cutoff = datetime.fromisoformat(period["corrections_cutoff"].replace("Z", "+00:00"))

    sites = {r["site"]: (ZoneInfo(r["timezone"]), r["format"]) for r in csv_rows(os.path.join(inp, "sites.csv"))}
    emps = {}
    for r in csv_rows(os.path.join(inp, "employees.csv")):
        emps[r["employee_id"]] = r["home_site"]
    rates = {}
    for r in csv_rows(os.path.join(inp, "rates.csv")):
