    for c in corr:
        k = (c["site"], c["punch_id"])
        a = c["action"].lower()
        if a == "void":
            if k in punches and k not in voided:
                voided.add(k)
                del punches[k]
                applied += 1
        elif a == "set":
            if k in punches:
                punches[k]["ts"] = to_epoch(datetime.fromisoformat(c["time"].replace("Z", "+00:00")))
                applied += 1
        elif a == "add":
            if k not in ever and c["site"] in sites:
                ever.add(k)
                punches[k] = {"site": c["site"], "id": c["punch_id"], "emp": c["employee"],
                              "dir": c["type"].upper(),
                              "ts": to_epoch(datetime.fromisoformat(c["time"].replace("Z", "+00:00")))}
                applied += 1

    byemp = {}
    for p in punches.values():
        if p["emp"] in emps:
            byemp.setdefault(p["emp"], []).append(p)

    def rnd(p):
        tz = sites[p["site"]][0]
        off = int(datetime.fromtimestamp(p["ts"], tz).utcoffset().total_seconds())
        loc = p["ts"] + off
        return ((loc + 180) // 360) * 360 - off

    def workday(ts, emp):
        return datetime.fromtimestamp(ts, sites[emps[emp]][0]).date()

    res = {}
    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0, "corrections_applied": applied}
    for e in emps:
        shifts = []
        ps = byemp.get(e, [])
        ps.sort(key=lambda p: (p["ts"], 0 if p["dir"] == "OUT" else 1, p["site"], p["id"]))
        kept = []
        for p in ps:
            if kept and kept[-1]["dir"] == p["dir"] and p["ts"] - kept[-1]["ts"] <= 300:
                p["r"] = rnd(p)
                if pstart <= workday(p["r"], e) <= pend:
                    exc["duplicates_dropped"] += 1
                continue
            p["r"] = rnd(p)
            kept.append(p)
        i = 0
        while i < len(kept):
            p = kept[i]
            if p["dir"] == "IN":
                nx = kept[i + 1] if i + 1 < len(kept) else None
                if nx and nx["dir"] == "OUT" and nx["r"] - p["r"] <= 16 * 3600:
                    shifts.append((p, nx))
                    i += 2
                    continue
                if pstart <= workday(p["r"], e) <= pend:
                    exc["open_shifts"] += 1
            else:
                if pstart <= workday(p["r"], e) <= pend:
                    exc["orphan_outs"] += 1
            i += 1
        rows = []
        for a, b in shifts:
            wd = workday(a["r"], e)
            if not (pstart <= wd <= pend):
                continue
            worked = max(0, (b["r"] - a["r"]) // 60)
            paid = worked - 30 if worked > 360 else worked
            tz = sites[a["site"]][0]
            night = 0
            for m in range(worked):
                h = datetime.fromtimestamp(a["r"] + 60 * m, tz).hour
                if h >= 22 or h < 6:
                    night += 1
            night = min(night, paid)
            rows.append({"in": a["r"], "wd": wd, "paid": paid, "night": night})
        rows.sort(key=lambda r: r["in"])
        daily = {}
        for r in rows:
            before = daily.get(r["wd"], 0)
            after = before + r["paid"]
            daily[r["wd"]] = after
            r["dot"] = max(0, after - 480) - max(0, before - 480)
        weekly = {}
        for r in rows:
            wk = r["wd"] - timedelta(days=r["wd"].weekday())
            before = weekly.get(wk, 0)
            reg = r["paid"] - r["dot"]
            after = before + reg
            weekly[wk] = after
            r["ot"] = r["dot"] + max(0, after - 2400) - max(0, before - 2400)
        pay = Fraction(0)
        for r in rows:
            rate = Fraction(0)
            for ef, rt in rates.get(e, []):
                if ef <= r["wd"]:
                    rate = rt
            r["regular"] = r["paid"] - r["ot"]
            pay += rate * (r["regular"] + Fraction(3, 2) * r["ot"]) / 60 + rate * Fraction(15, 100) * r["night"] / 60
        cents = int((pay * 100 + Fraction(1, 2)) // 1)
        res[e] = {"shifts": len(rows), "paid_minutes": sum(r["paid"] for r in rows),
                  "overtime_minutes": sum(r["ot"] for r in rows),
                  "night_minutes": sum(r["night"] for r in rows),
                  "gross": "%d.%02d" % divmod(cents, 100), "_c": cents}

    tot = {k: sum(v[k] for v in res.values()) for k in ("shifts", "paid_minutes", "overtime_minutes", "night_minutes")}
    tc = sum(v.pop("_c") for v in res.values())
    tot["gross"] = "%d.%02d" % divmod(tc, 100)
    out = {"period": {"start": period["start"], "end": period["end"]},
           "employees": res, "exceptions": exc, "totals": tot}
    with open(outp, "w") as f:
        json.dump(out, f, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
